public class Animacion extends Trabajo {

    protected int fotogramas;

    public Animacion(String codigo, String estudio, String proyecto,
                     double horasEstimadas, Horario horario,
                     int fotogramas) {

        // Inicializa y valida los datos comunes en Trabajo.
        super(codigo, estudio, proyecto, horasEstimadas, horario);

        // Rechaza cantidades de fotogramas no positivas.
        if (fotogramas <= 0) {
            throw new IllegalArgumentException(
                "La cantidad de fotogramas debe ser mayor que cero."
            );
        }

        this.fotogramas = fotogramas;
    }

    // Calcula las horas que corresponden a la cantidad de fotogramas.
    public double calcularHorasPorFotogramas() {
        // Dividir entre 50 equivale a multiplicar por 0.02.
        return fotogramas / 50.0;
    }

    // Calcula las horas facturables antes de redondearlas para el cobro.
    public double calcularHorasFacturables() {
        // Selecciona el mayor de los dos valores.
        return Math.max(horasEstimadas, calcularHorasPorFotogramas());
    }

    // Calcula el costo según el horario y las horas facturables.
    @Override
    public double calcularCosto() {
        double horasACobrar = Math.ceil(calcularHorasFacturables());

        // Suma la tarifa base y Q15 por cada hora o fracción.
        return tarifaBase() + 15.0 * horasACobrar;
    }

    // Devuelve el tiempo estimado de entrega en horas.
    @Override
    public int calcularTiempoEntrega() {
        // Selecciona el plazo correspondiente al horario.
        if (horario == Horario.DIURNO) {
            // Devuelve el plazo diurno.
            return 24;
        } else {
            // Devuelve el plazo nocturno.
            return 36;
        }
    }

    // Indica el máximo de intentos, incluyendo el primero.
    @Override
    public int getIntentosMaximos() {
        return 3;
    }

    // Identifica la categoría para consultas y reportes.
    @Override
    public String getCategoria() {
        return "Animación";
    }

    public int getFotogramas() {
        return fotogramas;
    }
}